from functools import wraps

def memoize(fn):
    cache = {}
    @wraps(fn)
    def inner(*args):
        if args not in cache:        # args is a tuple → hashable if its items are
            cache[args] = fn(*args)
        return cache[args]
    return inner

@memoize
def grid_paths(r, c):
    return 1 if r == 0 or c == 0 else grid_paths(r - 1, c) + grid_paths(r, c - 1)

